import React from 'react';
import { Menubar } from 'primereact/menubar';
import { useNavigate } from 'react-router-dom';

export default function Router() {
    const navigate = useNavigate();
    const items = [
        {
            label: 'Router',
            icon: 'pi pi-palette',
            items: [
                {
                    label: 'Styled',
                    command: () => {
                        navigate('/theming');
                    }
                },
                {
                    label: 'Unstyled',
                    command: () => {
                        navigate('/unstyled');
                    }
                }
            ]
        },
        {
            label: 'Programmatic',
            icon: 'pi pi-link',
            command: () => {
                navigate('/installation');
            }
        },
        {
            label: 'External',
            icon: 'pi pi-home',
            items: [
                {
                    label: 'React.js',
                    command: () => {
                        window.location.href = 'https://react.dev/';
                    }
                },
                {
                    label: 'Vite.js',
                    command: () => {
                        window.location.href = 'https://vitejs.dev/';
                    }
                }
            ]
        }
    ];

    return (
        <>
            <Menubar model={items} />
        </>
    )

}